-- Official SG past questions: 2017 autumn, questions 11–20.
-- Answers are checked against the official IPA answer key.
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29a-2017-q11','exam-sg','情報セキュリティ特性・否認防止','standard','single_choice','否認防止の特性に関する記述はどれか。','[{"id":"a","text":"ある利用者があるシステムを利用したという事実が証明可能である。"},{"id":"b","text":"認可された利用者が要求したときにアクセスが可能である。"},{"id":"c","text":"認可された利用者に対してだけ情報を使用させる又は開示する。"},{"id":"d","text":"利用者の行動と意図した結果とが一貫性をもつ。"}]','"a"','正解はア。否認防止は，処理や事象の発生と関係主体を後から証明できる性質である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q12','exam-sg','物理セキュリティ・サポートユーティリティ','standard','single_choice','JIS Q 27002:2014の「サポートユーティリティ」に該当するものはどれか。','[{"id":"a","text":"サーバ室の空調"},{"id":"b","text":"サーバの保守契約"},{"id":"c","text":"特権管理プログラム"},{"id":"d","text":"ネットワーク管理者"}]','"a"','正解はア。空調や電気，通信サービスなど，情報システム稼働の基盤となるライフラインが該当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q13','exam-sg','情報漏えい対策・DLP','standard','single_choice','秘密情報を判別し，漏えいにつながる操作に警告したり，自動的に無効化したりするものはどれか。','[{"id":"a","text":"DLP"},{"id":"b","text":"DMZ"},{"id":"c","text":"IDS"},{"id":"d","text":"IPS"}]','"a"','正解はア。DLPは機密情報の持出しや送信などを検知・監視し，必要に応じて遮断する仕組みである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q14','exam-sg','ログ監視・SIEM','standard','single_choice','SIEM（Security Information and Event Management）の機能はどれか。','[{"id":"a","text":"隔離された仮想環境でファイルを実行し，通信などの振る舞いを監視する。"},{"id":"b","text":"様々な機器から集められたログを総合的に分析し，管理者による分析を支援する。"},{"id":"c","text":"ネットワーク機器を集中制御し，構成や設定を動的に変更する。"},{"id":"d","text":"通信内容を検査してアプリケーション単位で制御する。"}]','"b"','正解はイ。SIEMは複数機器のログを集約・相関分析し，脅威の兆候を検知する支援を行う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q15','exam-sg','物理セキュリティ・入退室管理','standard','single_choice','入退室時にIDカードの履歴を照合し，入室に使われなかったカードでの退室など矛盾した入退室を禁止する仕組みはどれか。','[{"id":"a","text":"TPMOR"},{"id":"b","text":"アンチパスバック"},{"id":"c","text":"インターロックゲート"},{"id":"d","text":"パニックオープン"}]','"b"','正解はイ。アンチパスバックは入退室記録の矛盾を検知し，共連れなどを抑止する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q16','exam-sg','シャドーIT・クラウド利用','standard','single_choice','シャドーITに該当するものはどれか。','[{"id":"a","text":"ITを活用して環境負荷を低減する取組み"},{"id":"b","text":"IT部門の公式な許可を得ず，従業員や部門が業務に利用している端末やクラウドサービス"},{"id":"c","text":"画面やキー入力を盗み見て情報を盗み出すこと"},{"id":"d","text":"攻撃対象の弱点を探すために情報を収集すること"}]','"b"','正解はイ。シャドーITは組織の承認・管理を経ずに業務利用される端末やサービスを指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q17','exam-sg','情報隠蔽・ステガノグラフィ','standard','single_choice','ステガノグラフィはどれか。','[{"id":"a","text":"画像などのデータの中に，秘密情報を他者に気付かれないように埋め込む。"},{"id":"b","text":"検索エンジンに閲覧者とは異なる内容を送信し，検索順位を上げる。"},{"id":"c","text":"テストデータを入力し，製品の応答から脆弱性を検出する。"},{"id":"d","text":"ゆがんだ文字画像を表示して人間による入力を確認する。"}]','"a"','正解はア。ステガノグラフィは画像や音声などに別の情報を目立たない形で埋め込む技術である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q18','exam-sg','認証・パスワードハッシュ','standard','single_choice','パスワードを用いて利用者を認証する方法のうち，適切なものはどれか。','[{"id":"a","text":"パスワードに対応する利用者IDのハッシュ値を登録し，入力パスワードをハッシュ化して比較する。"},{"id":"b","text":"利用者IDのハッシュ値を登録し，入力された利用者IDをハッシュ化して比較する。"},{"id":"c","text":"パスワードをハッシュ値に変換して登録し，認証時に入力パスワードをハッシュ化して比較する。"},{"id":"d","text":"パスワードのハッシュ値を登録し，入力された利用者IDをハッシュ化して比較する。"}]','"c"','正解はウ。パスワードをハッシュ化して保存し，認証時に入力値から計算した値と照合する。実運用ではソルト付きの専用パスワードハッシュを使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q19','exam-sg','無線LAN・認証','standard','single_choice','参加者が毎回変わる公開セミナで無線LANを提供する。参加者の端末以外からアクセスポイントへの接続を防ぐために効果がある対策はどれか。','[{"id":"a","text":"DHCPで動的に割り当てるIPアドレス範囲をセミナごとに変更する。"},{"id":"b","text":"URLフィルタリング条件をセミナごとに変更する。"},{"id":"c","text":"参加者の端末とアクセスポイントで事前共有する鍵をセミナごとに変更する。"},{"id":"d","text":"プライバシーセパレータの設定をセミナごとに変更する。"}]','"c"','正解はウ。参加者ごとに共有鍵を適切に配布・更新することで，許可された端末だけが無線LANに接続できるようにする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q20','exam-sg','Webセキュリティ・WAF','standard','single_choice','WAFの説明として適切なものはどれか。','[{"id":"a","text":"DMZのWebサーバへの侵入を外部から実際に試みる。"},{"id":"b","text":"TLSの暗号化・復号を専用ハードウェアで処理し，WebサーバのCPU負荷を軽減する。"},{"id":"c","text":"管理者の回答に基づいて組織の情報セキュリティ対策レベルを診断する。"},{"id":"d","text":"Webアプリケーションへの通信内容を検査し，不正な操作を遮断する。"}]','"d"','正解はエ。WAFはHTTP通信内容を検査し，XSSやSQLインジェクションなどWebアプリケーションへの攻撃を検知・遮断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja');
